    tail.position.set(-0.44, 0, 0);
    const fin = mesh(new ConeGeometry(0.2, 0.3, 3, 1), mat(belly, { roughness: 0.5 }));
    fin.rotation.z = Math.PI / 2;
    fin.rotation.y = Math.PI / 2;
    fin.scale.set(1, 0.35, 1);
    tail.add(fin);
    group.add(tail);
