        { kind: "gull", count: 3, hMin: 1, hMax: 2.6, radius: 8 },
        { kind: "snake", count: 3, hMin: 2.6, hMax: 11, radius: 7 },
        { kind: "monkey", count: 4, hMin: 3.5, hMax: 14, radius: 10 },
        { kind: "turtle", count: 4, hMin: 0.7, hMax: 2.2, radius: 7 }
