      mob.x = spot.x;
      mob.z = spot.z;
      mob.y = spot.h;
      mob.home = { x: spot.x, z: spot.z };
      mob.hp = mob.maxHp;
      mob.alive = true;
      mob.state = "idle";
      mob.stateTime = 0;
      mob.deadTimer = 0;
      mob.alerted = false;
      mob.group.visible = true;
      mob.group.rotation.set(0, 0, 0);
